// Hexana scripting API — format-specific types behind `binary.raw`.
//
// Generated by reflection over the internal provider hierarchy, so it is
// large and it tracks internals rather than a stable contract. Start from
// hexana-scripting.d.ts, which documents the members that work the same
// way for every binary format; come here only when a script needs
// something only one format has.

/**
 * Base shape of `binary.raw`, common to every format.
 */
interface BinaryProvider {
  bytes: {
    indices: {
      endExclusive: number;
      endInclusive: number;
      first: number;
      last: number;
      start: number;
      step: number;
    };
    lastIndex: number;
    size: number;
  };
  sizeAnalysis?: {
    children: BinarySizeNode[];
    name: string;
    offset: number;
    size: number;
  };
  strings: {
    index: number;
    offset: number;
    size: number;
    tag?: string;
    value: string;
  }[];
  structureRanges: {
    label: string;
    offset: number;
    size: number;
    tabName?: string;
  }[];
}

